export const getConfigRetrieveUrl = () => {
  return `/api/v1/config`;
};

/**
 * Vrací statické texty a hodnoty, které frontend potřebuje na víc místech a nemění se podle uživatele: text horní lišty, kontaktní e-mail a telefon, odkaz na Instagram, číslo bankovního účtu (pro zobrazení platebních instrukcí) a číselníky `paymentMethods`/`deliveryTypes` s českými popisky (`value` = hodnota, kterou posíláš v `POST /orders`, `label` = text pro uživatele). Volej jednou při startu appky, výsledek je bezpečné cachovat - hodnoty se mění jen ručně přes env proměnné na backendu.
 * @summary Konfigurace obchodu pro hlavičku, patičku a checkout
 */
export const configRetrieve = async (
  options?: Parameters<typeof apiFetch>[1],
): Promise<ConfigResponse> => {
  return apiFetch<ConfigResponse>(getConfigRetrieveUrl(), {
    ...options,
    method: "GET",
  });
};

export const getConfigRetrieveQueryKey = () => {
  return [`/api/v1/config`] as const;
};

export const getConfigRetrieveQueryOptions = <
  TData = Awaited<ReturnType<typeof configRetrieve>>,
  TError = ErrorType<unknown>,
>(options?: {
  query?: Partial<UseQueryOptions<Awaited<ReturnType<typeof configRetrieve>>, TError, TData>>;
  request?: SecondParameter<typeof apiFetch>;
}) => {
  const { query: queryOptions, request: requestOptions } = options ?? {};

  const queryKey = queryOptions?.queryKey ?? getConfigRetrieveQueryKey();

  const queryFn: QueryFunction<Awaited<ReturnType<typeof configRetrieve>>> = ({ signal }) =>
    configRetrieve({ signal, ...requestOptions });

  return { queryKey, queryFn, ...queryOptions } as UseQueryOptions<
    Awaited<ReturnType<typeof configRetrieve>>,
    TError,
    TData
  > & { queryKey: DataTag<QueryKey, TData, TError> };
};

